#include <print>
#include <memory>
#include <utility>

int main() {
    auto p1 = std::make_unique<int>(7);
    auto p2 = p1;
    auto p3 = std::move(p1);
    std::println("p1 空了吗: {}", p1 == nullptr);
    std::println("p3 的值: {}", *p3);
    return 0;
}
// 放开复印那行报 use of deleted function：两张纸条各自释放同一块内存就是双重释放

